; The barrow. In at the bottom up the steps, through a short dark passage into the hall, the
; side room off it to the west, and the tomb at the back. Lit by the sconces and nothing else.

[map]
id = barrow
name = The Barrow
tileset = crypt
size = 40 30
dark = yes
ambient = 0.07
music = Underground

[legend]
, = floor
w = floor-worn
s = floor-shadow
~ = steps
# = wall-top
F = wall-face
N = wall-niche
B = wall-base
r = rubble
b = bones
c = cobweb

